import { GoogleGenAI, Type, Schema } from "@google/genai";
import { getAiImportPrompt } from "../constants";
import { LogicModel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const logicModelSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    organization: { type: Type.STRING, description: "Name of the organization" },
    program: { type: Type.STRING, description: "Name of the program" },
    problemStatement: { type: Type.STRING, description: "Description of the problem" },
    inputs: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Resources invested" 
    },
    activities: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Specific actions and events" 
    },
    outputs: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Direct tangible products" 
    },
    shortTermOutcomes: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Immediate changes in knowledge or skills" 
    },
    mediumTermOutcomes: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Intermediate changes in behavior" 
    },
    longTermOutcomes: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Broad changes in condition" 
    },
    impact: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING }, 
      description: "Ultimate systemic changes" 
    },
  },
  required: [
    "organization", "program", "problemStatement", 
    "inputs", "activities", "outputs", 
    "shortTermOutcomes", "mediumTermOutcomes", "longTermOutcomes", 
    "impact"
  ],
};

export const parseLogicModelFromMarkdown = async (markdown: string): Promise<LogicModel> => {
  try {
    const prompt = getAiImportPrompt(markdown);

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: logicModelSchema,
        temperature: 0.1,
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini.");
    }

    const data = JSON.parse(text) as LogicModel;
    return data;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to parse Logic Model from text.");
  }
};

import React from 'react';
