import { GoogleGenAI, Type, Schema } from "@google/genai";
import { getAiCritiquePrompt } from "../constants";
import { LogicModel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fieldSchema = (contentType: Type): Schema => ({
  type: Type.OBJECT,
  properties: {
    content: contentType === Type.ARRAY ? { type: Type.ARRAY, items: { type: Type.STRING } } : { type: Type.STRING },
    critique: { type: Type.STRING, description: "Constructive feedback on this specific section" }
  },
  required: ["content", "critique"]
});

const logicModelSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    organization: { type: Type.STRING },
    program: { type: Type.STRING },
    problemStatement: fieldSchema(Type.STRING),
    inputs: fieldSchema(Type.ARRAY),
    activities: fieldSchema(Type.ARRAY),
    outputs: fieldSchema(Type.ARRAY),
    shortTermOutcomes: fieldSchema(Type.ARRAY),
    mediumTermOutcomes: fieldSchema(Type.ARRAY),
    longTermOutcomes: fieldSchema(Type.ARRAY),
    impact: fieldSchema(Type.ARRAY),
  },
  required: [
    "organization", "program", "problemStatement", "inputs", "activities", 
    "outputs", "shortTermOutcomes", "mediumTermOutcomes", "longTermOutcomes", "impact"
  ],
};

export const parseAndCritiqueLogicModel = async (markdown: string): Promise<LogicModel> => {
  const prompt = getAiCritiquePrompt(markdown);
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: {
      responseMimeType: 'application/json',
      responseSchema: logicModelSchema,
      temperature: 0.2,
    }
  });

  if (!response.text) throw new Error("No response from AI.");
  return JSON.parse(response.text) as LogicModel;
};

import React from 'react';
import { LogicModel } from '../types';

interface LogicModelEditorProps {
  model: LogicModel;
  onUpdate: (updatedModel: LogicModel) => void;
  onReAnalyze: () => void;
  isAnalyzing: boolean;
}

const EditableSection: React.FC<{
  title: string;
  field: keyof LogicModel;
  model: LogicModel;
  onUpdate: (updatedModel: LogicModel) => void;
}> = ({ title, field, model, onUpdate }) => {
  const data = model[field] as any;
  const isArray = Array.isArray(data.content);

  const handleChange = (val: string) => {
    const newModel = { ...model };
    if (isArray) {
      (newModel[field] as any).content = val.split('\n').filter(l => l.trim() !== '');
    } else {
      (newModel[field] as any).content = val;
    }
    onUpdate(newModel);
  };

  const textValue = isArray ? data.content.join('\n') : data.content;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 border-b border-gray-100 pb-6 mb-6 last:border-0">
      <div className="space-y-2">
        <label className="block text-xs font-bold uppercase tracking-wider text-slate-500">{title}</label>
        <textarea
          className="w-full min-h-[120px] p-3 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all font-mono"
          value={textValue}
          onChange={(e) => handleChange(e.target.value)}
          placeholder={isArray ? "One item per line..." : "Enter text here..."}
        />
        {isArray && <p className="text-[10px] text-gray-400 italic">Tip: Use new lines for separate bullet points.</p>}
      </div>
      <div className="bg-amber-50 border border-amber-100 rounded-lg p-4 self-start">
        <h5 className="text-[10px] font-bold text-amber-700 uppercase tracking-widest mb-2 flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 mr-1">
            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
          </svg>
          AI Critique
        </h5>
        <p className="text-xs text-amber-900 leading-relaxed italic">
          {data.critique || "Everything looks good here! No specific suggestions."}
        </p>
      </div>
    </div>
  );
};

const LogicModelEditor: React.FC<LogicModelEditorProps> = ({ model, onUpdate, onReAnalyze, isAnalyzing }) => {
  return (
    <div className="bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden">
      <div className="bg-slate-800 text-white px-6 py-4 flex justify-between items-center">
        <div>
          <h3 className="font-bold text-lg">{model.program || 'Draft Logic Model'}</h3>
          <p className="text-xs opacity-70">Review the AI critique and refine the text below.</p>
        </div>
        <button
          onClick={onReAnalyze}
          disabled={isAnalyzing}
          className="bg-blue-600 hover:bg-blue-500 disabled:bg-slate-600 px-4 py-2 rounded-lg text-sm font-bold transition-colors flex items-center space-x-2"
        >
          {isAnalyzing ? (
            <><div className="animate-spin h-4 w-4 border-2 border-white/30 border-t-white rounded-full"></div><span>Refining...</span></>
          ) : (
            <><span>Re-Analyze Edits</span></>
          )}
        </button>
      </div>

      <div className="p-6">
        <div className="grid grid-cols-2 gap-4 mb-8">
           <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Organization</label>
              <input 
                type="text" 
                className="w-full p-2 border-b font-medium focus:border-blue-500 outline-none"
                value={model.organization} 
                onChange={e => onUpdate({...model, organization: e.target.value})}
              />
           </div>
           <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Program</label>
              <input 
                type="text" 
                className="w-full p-2 border-b font-medium focus:border-blue-500 outline-none"
                value={model.program} 
                onChange={e => onUpdate({...model, program: e.target.value})}
              />
           </div>
        </div>

        <EditableSection title="Problem Statement" field="problemStatement" model={model} onUpdate={onUpdate} />
        <EditableSection title="Inputs" field="inputs" model={model} onUpdate={onUpdate} />
        <EditableSection title="Activities" field="activities" model={model} onUpdate={onUpdate} />
        <EditableSection title="Outputs" field="outputs" model={model} onUpdate={onUpdate} />
        <EditableSection title="Short-Term Outcomes" field="shortTermOutcomes" model={model} onUpdate={onUpdate} />
        <EditableSection title="Medium-Term Outcomes" field="mediumTermOutcomes" model={model} onUpdate={onUpdate} />
        <EditableSection title="Long-Term Outcomes" field="longTermOutcomes" model={model} onUpdate={onUpdate} />
        <EditableSection title="Impact" field="impact" model={model} onUpdate={onUpdate} />
      </div>
    </div>
  );
};

export default LogicModelEditor;

import React, { useState, useEffect, useRef } from 'react';
import { ProcessingFile, LogicModel } from './types';
import FileUpload from './components/FileUpload';
import LogicModelEditor from './components/LogicModelEditor';
import { convertFileToMarkdown } from './services/fileService';
import { parseAndCritiqueLogicModel } from './services/geminiService';

const App: React.FC = () => {
  const [files, setFiles] = useState<ProcessingFile[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const processingRef = useRef(false);

  const handleFilesSelected = (newFiles: File[]) => {
    const newProcessingFiles: ProcessingFile[] = newFiles.map(file => ({
      id: Math.random().toString(36).substring(7),
      file,
      status: 'pending'
    }));
    setFiles(prev => [...prev, ...newProcessingFiles]);
  };

  useEffect(() => {
    const processQueue = async () => {
      if (processingRef.current) return;
      const pendingFile = files.find(f => f.status === 'pending');
      if (!pendingFile) return;

      processingRef.current = true;
      setIsProcessing(true);
      const fileId = pendingFile.id;

      try {
        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'converting' } : f));
        const markdown = await convertFileToMarkdown(pendingFile.file);

        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'analyzing', markdown } : f));
        const result = await parseAndCritiqueLogicModel(markdown);

        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'editing', result } : f));
      } catch (error: any) {
        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'error', error: error.message } : f));
      } finally {
        processingRef.current = false;
        setIsProcessing(false);
      }
    };
    processQueue();
  }, [files, isProcessing]);

  const updateModel = (fileId: string, updatedModel: LogicModel) => {
    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, result: updatedModel } : f));
  };

  const reAnalyzeModel = async (fileId: string) => {
    const file = files.find(f => f.id === fileId);
    if (!file || !file.result) return;

    // We re-analyze based on the current EDITED text, converted back to markdown or a prompt
    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'analyzing' } : f));
    setIsProcessing(true);

    try {
      // Create a text representation of the edited model to re-critique
      const textForCritique = `
        Organization: ${file.result.organization}
        Program: ${file.result.program}
        Problem: ${file.result.problemStatement.content}
        Inputs: ${file.result.inputs.content.join(', ')}
        Activities: ${file.result.activities.content.join(', ')}
        Outputs: ${file.result.outputs.content.join(', ')}
        Short-Term: ${file.result.shortTermOutcomes.content.join(', ')}
        Medium-Term: ${file.result.mediumTermOutcomes.content.join(', ')}
        Long-Term: ${file.result.longTermOutcomes.content.join(', ')}
        Impact: ${file.result.impact.content.join(', ')}
      `;
      const result = await parseAndCritiqueLogicModel(textForCritique);
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'editing', result } : f));
    } catch (e: any) {
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'error', error: e.message } : f));
    } finally {
      setIsProcessing(false);
    }
  };

  const finalizeModel = (fileId: string) => {
    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'completed' } : f));
  };

  const normalizeText = (text: string): string => {
    if (!text) return '';
    return text.replace(/[\r\n]+/g, " ").trim();
  };

  const handleExportCSV = () => {
    const completed = files.filter(f => (f.status === 'completed' || f.status === 'editing') && f.result);
    if (completed.length === 0) return;

    const headers = ['Organization', 'Program', 'Section', 'Content'];
