    completed.forEach(f => {
      const m = f.result!;
      const fields = [
        { key: 'Problem', val: m.problemStatement.content },
        { key: 'Inputs', val: m.inputs.content },
        { key: 'Activities', val: m.activities.content },
        { key: 'Outputs', val: m.outputs.content },
        { key: 'Short-Term Outcomes', val: m.shortTermOutcomes.content },
        { key: 'Medium-Term Outcomes', val: m.mediumTermOutcomes.content },
        { key: 'Long-Term Outcomes', val: m.longTermOutcomes.content },
        { key: 'Impact', val: m.impact.content },
