declare global {
  interface Window {
    pdfjsLib: any;
    mammoth: any;
    JSZip: any;
    TurndownService: any;
  }
}

const checkLibs = () => {
  if (!window.mammoth) console.warn('Mammoth.js not loaded');
  if (!window.pdfjsLib) console.warn('PDF.js not loaded');
  if (!window.JSZip) console.warn('JSZip not loaded');
  if (!window.TurndownService) console.warn('TurndownService not loaded');
};

export const extractTextFromPdf = async (file: File): Promise<string> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = '';
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(' ');
      fullText += `\n\n## Page ${i}\n\n${pageText}`;
    }
    return fullText;
  } catch (error) {
    console.error('PDF Extraction Error:', error);
    throw new Error('Failed to extract text from PDF.');
  }
};

export const extractTextFromDocx = async (file: File): Promise<string> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const result = await window.mammoth.convertToHtml({ arrayBuffer });
    const turndownService = new window.TurndownService({ headingStyle: 'atx', bulletListMarker: '-' });
    return turndownService.turndown(result.value);
  } catch (error) {
    console.error('Docx Extraction Error:', error);
    throw new Error('Failed to extract text from DOCX.');
  }
};

export const extractTextFromPptx = async (file: File): Promise<string> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = await window.JSZip.loadAsync(arrayBuffer);
    const slideFiles = Object.keys(zip.files).filter(name => name.startsWith('ppt/slides/slide') && name.endsWith('.xml'));

    slideFiles.sort((a, b) => {
      const numA = parseInt(a.match(/\d+/)![0]);
      const numB = parseInt(b.match(/\d+/)![0]);
      return numA - numB;
    });

    let fullText = '';
    const parser = new DOMParser();

    for (const slidePath of slideFiles) {
      const content = await zip.file(slidePath)!.async('text');
      const xmlDoc = parser.parseFromString(content, 'application/xml');
      const textNodes = xmlDoc.getElementsByTagName('a:t');
      const slideText = Array.from(textNodes).map(node => node.textContent).join(' ');
      const slideNum = slidePath.match(/\d+/)![0];
      fullText += `\n\n## Slide ${slideNum}\n\n${slideText}`;
    }

    return fullText;
  } catch (error) {
    console.error('PPTX Extraction Error:', error);
    throw new Error('Failed to extract text from PPTX.');
  }
};

export const convertFileToMarkdown = async (file: File): Promise<string> => {
  const name = file.name.toLowerCase();
  if (name.endsWith('.pdf')) return extractTextFromPdf(file);
  if (name.endsWith('.docx')) return extractTextFromDocx(file);
  if (name.endsWith('.pptx')) return extractTextFromPptx(file);
  throw new Error(`Unsupported file format: ${file.name}`);
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { getAiCritiquePrompt } from "../constants";
import { LogicModel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fieldSchema = (contentType: Type): Schema => ({
  type: Type.OBJECT,
  properties: {
    content: contentType === Type.ARRAY ? { type: Type.ARRAY, items: { type: Type.STRING } } : { type: Type.STRING },
    critique: { type: Type.STRING, description: "Constructive feedback on this specific section" }
  },
  required: ["content", "critique"]
});

const logicModelSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    organization: { type: Type.STRING },
    program: { type: Type.STRING },
    problemStatement: fieldSchema(Type.STRING),
    inputs: fieldSchema(Type.ARRAY),
    activities: fieldSchema(Type.ARRAY),
    outputs: fieldSchema(Type.ARRAY),
    shortTermOutcomes: fieldSchema(Type.ARRAY),
    mediumTermOutcomes: fieldSchema(Type.ARRAY),
    longTermOutcomes: fieldSchema(Type.ARRAY),
    impact: fieldSchema(Type.ARRAY),
  },
  required: [
    "organization", "program", "problemStatement", "inputs", "activities", 
    "outputs", "shortTermOutcomes", "mediumTermOutcomes", "longTermOutcomes", "impact"
  ],
};

export const parseAndCritiqueLogicModel = async (markdown: string): Promise<LogicModel> => {
  const prompt = getAiCritiquePrompt(markdown);
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: 'application/json',
      responseSchema: logicModelSchema,
      temperature: 0.1,
    }
  });

  if (!response.text) throw new Error("No response from AI.");
  return JSON.parse(response.text) as LogicModel;
};

import React, { useCallback } from 'react';

interface FileUploadProps {
  onFilesSelected: (files: File[]) => void;
  disabled?: boolean;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFilesSelected, disabled }) => {
  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      if (disabled) return;

      const droppedFiles = Array.from<File>(e.dataTransfer.files).filter(
        (file) => 
            file.type === 'application/pdf' || 
            file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' ||
            file.type === 'application/vnd.openxmlformats-officedocument.presentationml.presentation' ||
            file.name.endsWith('.pdf') ||
            file.name.endsWith('.docx') ||
            file.name.endsWith('.pptx')
      );

      if (droppedFiles.length > 0) {
        onFilesSelected(droppedFiles);
      }
    },
    [disabled, onFilesSelected]
  );

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (disabled || !e.target.files) return;
    const selectedFiles = Array.from<File>(e.target.files);
    onFilesSelected(selectedFiles);
    e.target.value = ''; 
  };

  return (
    <div
      onDrop={handleDrop}
      onDragOver={handleDragOver}
      className={`border-2 border-dashed rounded-xl p-10 text-center transition-all duration-200 
        ${disabled 
            ? 'border-gray-300 bg-gray-50 cursor-not-allowed opacity-60' 
            : 'border-blue-300 bg-blue-50/50 hover:bg-blue-50 hover:border-blue-500 cursor-pointer'
        }`}
    >
      <input
        type="file"
        multiple
        accept=".pdf,.docx,.pptx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.presentationml.presentation"
        onChange={handleInputChange}
        disabled={disabled}
        className="hidden"
        id="file-upload"
      />
      <label htmlFor="file-upload" className={disabled ? 'cursor-not-allowed' : 'cursor-pointer'}>
        <div className="flex flex-col items-center justify-center space-y-3">
          <div className="p-3 bg-white rounded-full shadow-sm">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8 text-blue-600">
              <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m3.75 9v6m3-3H9m1.5-12H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
            </svg>
          </div>
          <div className="text-gray-700">
            <span className="font-semibold text-blue-600">Click to upload</span> or drag and drop
          </div>
          <p className="text-sm text-gray-500">
            Support for PDF, Word (.docx), and PowerPoint (.pptx)
          </p>
        </div>
      </label>
    </div>
  );
};

