import { GoogleGenAI, Type, Schema } from "@google/genai";
import { getAiCritiquePrompt } from "../constants";
import { LogicModel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const groupSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING, description: "Name of the category or group (e.g., 'Staff', 'Parents'). Use 'General' if no group." },
    items: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["name", "items"]
};

const fieldSchema = (contentType: Type): Schema => ({
  type: Type.OBJECT,
  properties: {
    // If it's an ARRAY type field, the content is an array of Groups
    content: contentType === Type.ARRAY 
      ? { type: Type.ARRAY, items: groupSchema } 
      : { type: Type.STRING },
    critique: { type: Type.STRING, description: "Constructive feedback on this specific section" }
  },
  required: ["content", "critique"]
});

const logicModelSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    organization: { type: Type.STRING },
    program: { type: Type.STRING },
    problemStatement: fieldSchema(Type.STRING),
    inputs: fieldSchema(Type.ARRAY),
    activities: fieldSchema(Type.ARRAY),
    outputs: fieldSchema(Type.ARRAY),
    shortTermOutcomes: fieldSchema(Type.ARRAY),
    mediumTermOutcomes: fieldSchema(Type.ARRAY),
    longTermOutcomes: fieldSchema(Type.ARRAY),
    impact: fieldSchema(Type.ARRAY),
  },
  required: [
    "organization", "program", "problemStatement", "inputs", "activities", 
    "outputs", "shortTermOutcomes", "mediumTermOutcomes", "longTermOutcomes", "impact"
  ],
};

// Input can be a string (markdown) or an array of strings (base64 images)
export const parseAndCritiqueLogicModel = async (input: string | string[]): Promise<LogicModel> => {
  const isVision = Array.isArray(input);
  const prompt = getAiCritiquePrompt(isVision);

  let contents: any;

  if (isVision) {
    // Construct the payload for vision (text prompt + images)
    const parts: any[] = [{ text: prompt }];
    (input as string[]).forEach(base64Image => {
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: base64Image
        }
      });
    });
    contents = { parts };
  } else {
    // Text-only payload
    contents = [
      { text: prompt },
      { text: `\n\nDocument Content:\n---\n${input}\n---` }
    ];
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: contents,
    config: {
      responseMimeType: 'application/json',
      responseSchema: logicModelSchema,
      temperature: 0.2,
    }
  });

  if (!response.text) throw new Error("No response from AI.");
  return JSON.parse(response.text) as LogicModel;
};

import React from 'react';
import { LogicModel, LogicModelGroup } from '../types';

interface LogicModelEditorProps {
  model: LogicModel;
  onUpdate: (updatedModel: LogicModel) => void;
  onReAnalyze: () => void;
  isAnalyzing: boolean;
}

const EditableGroupSection: React.FC<{
  title: string;
  field: keyof LogicModel;
  model: LogicModel;
  onUpdate: (updatedModel: LogicModel) => void;
}> = ({ title, field, model, onUpdate }) => {
  const fieldData = model[field] as { content: LogicModelGroup[], critique: string };
  const groups = fieldData.content;

  const handleGroupChange = (groupIndex: number, newItemsText: string) => {
    const newGroups = [...groups];
    newGroups[groupIndex].items = newItemsText.split('\n').filter(l => l.trim() !== '');

    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  const handleGroupNameChange = (groupIndex: number, newName: string) => {
    const newGroups = [...groups];
    newGroups[groupIndex].name = newName;
    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  const addGroup = () => {
    const newGroups = [...groups, { name: 'New Category', items: [] }];
    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  const removeGroup = (index: number) => {
    if (!window.confirm("Remove this group?")) return;
    const newGroups = groups.filter((_, i) => i !== index);
    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 border-b border-gray-100 pb-8 mb-8 last:border-0">
      {/* Title Column */}
      <div className="lg:col-span-3">
