import React, { useState, useEffect, useRef } from 'react';
import { ProcessingFile, LogicModel, LogicModelGroup } from './types';
import FileUpload from './components/FileUpload';
import LogicModelEditor from './components/LogicModelEditor';
import { convertFileToMarkdown, convertPdfToImages } from './services/fileService';
import { parseAndCritiqueLogicModel } from './services/geminiService';

const App: React.FC = () => {
  const [files, setFiles] = useState<ProcessingFile[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const processingRef = useRef(false);

  const handleFilesSelected = (newFiles: File[]) => {
    const newProcessingFiles: ProcessingFile[] = newFiles.map(file => ({
      id: Math.random().toString(36).substring(7),
      file,
      status: 'pending'
    }));
    setFiles(prev => [...prev, ...newProcessingFiles]);
  };

  useEffect(() => {
    const processQueue = async () => {
      if (processingRef.current) return;
      const pendingFile = files.find(f => f.status === 'pending');
      if (!pendingFile) return;

      processingRef.current = true;
      setIsProcessing(true);
      const fileId = pendingFile.id;

      try {
        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'converting' } : f));

        let inputForGemini: string | string[];

        // Decide pipeline based on file type
        if (pendingFile.file.type === 'application/pdf' || pendingFile.file.name.endsWith('.pdf')) {
           // Vision Pipeline
           inputForGemini = await convertPdfToImages(pendingFile.file);
        } else {
           // Text Pipeline
           inputForGemini = await convertFileToMarkdown(pendingFile.file);
        }

        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'analyzing' } : f));
        const result = await parseAndCritiqueLogicModel(inputForGemini);

        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'editing', result } : f));
      } catch (error: any) {
        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'error', error: error.message } : f));
      } finally {
        processingRef.current = false;
        setIsProcessing(false);
      }
    };
    processQueue();
  }, [files, isProcessing]);

  const updateModel = (fileId: string, updatedModel: LogicModel) => {
    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, result: updatedModel } : f));
  };

  const reAnalyzeModel = async (fileId: string) => {
    const file = files.find(f => f.id === fileId);
    if (!file || !file.result) return;

    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'analyzing' } : f));
    setIsProcessing(true);

    try {
      // For re-analysis, we just use the text representation of the current state
      // We do not re-send images as we are refining the logic, not the extraction.
      const formatGroups = (groups: LogicModelGroup[]) => 
         groups.map(g => `Group: ${g.name}\nItems: ${g.items.join(', ')}`).join('\n');

      const textForCritique = `
        Organization: ${file.result.organization}
        Program: ${file.result.program}
        Problem: ${file.result.problemStatement.content}
        Inputs: \n${formatGroups(file.result.inputs.content)}
        Activities: \n${formatGroups(file.result.activities.content)}
        Outputs: \n${formatGroups(file.result.outputs.content)}
        Short-Term: \n${formatGroups(file.result.shortTermOutcomes.content)}
        Medium-Term: \n${formatGroups(file.result.mediumTermOutcomes.content)}
        Long-Term: \n${formatGroups(file.result.longTermOutcomes.content)}
        Impact: \n${formatGroups(file.result.impact.content)}
      `;
      const result = await parseAndCritiqueLogicModel(textForCritique);
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'editing', result } : f));
    } catch (e: any) {
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'error', error: e.message } : f));
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExportCSV = () => {
    const completed = files.filter(f => (f.status === 'editing' || f.status === 'completed') && f.result);
    if (completed.length === 0) return;

    const headers = ['Organization', 'Program', 'Domain', 'Group', 'Content'];
    const rows: string[][] = [];

    completed.forEach(f => {
      const m = f.result!;

      const pushGroups = (domain: string, groups: LogicModelGroup[]) => {
         groups.forEach(g => {
            g.items.forEach(item => {
               rows.push([m.organization, m.program, domain, g.name, item]);
            });
         });
      };

      rows.push([m.organization, m.program, 'Problem Statement', 'General', m.problemStatement.content]);
      pushGroups('Inputs', m.inputs.content);
      pushGroups('Activities', m.activities.content);
      pushGroups('Outputs', m.outputs.content);
      pushGroups('Short-Term Outcomes', m.shortTermOutcomes.content);
      pushGroups('Medium-Term Outcomes', m.mediumTermOutcomes.content);
      pushGroups('Long-Term Outcomes', m.longTermOutcomes.content);
      pushGroups('Impact', m.impact.content);
    });

    const csvContent = [
      headers.map(h => `"${h}"`).join(','),
      ...rows.map(row => row.map(c => `"${String(c).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `logic_models_granular_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="bg-indigo-600 text-white p-1.5 rounded-lg shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" />
                </svg>
             </div>
             <h1 className="text-xl font-bold text-slate-800">Logic Model Refiner <span className="text-xs font-normal text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full ml-2">Vision Enabled</span></h1>
          </div>
          <button 
            onClick={handleExportCSV}
            className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-700 transition-colors shadow-sm disabled:opacity-50"
            disabled={files.length === 0}
          >
            Export All Data
          </button>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        <section className="text-center space-y-3 max-w-3xl mx-auto">
            <h2 className="text-3xl font-bold text-slate-900 leading-tight">Extract & Refine Your Program Data</h2>
            <p className="text-slate-600">
                Upload logic models. <strong>PDFs use AI Vision</strong> to detect visual groups (e.g., stakeholders, themes).
                Word/PPT use text extraction.
            </p>
        </section>

        <section>
          <FileUpload onFilesSelected={handleFilesSelected} disabled={isProcessing} />
        </section>

        {files.length > 0 && (
          <div className="space-y-12">
            {files.map(file => (
              <div key={file.id} className="space-y-4">
                <div className="flex items-center justify-between bg-white p-3 rounded-lg border border-gray-200 shadow-sm">
                   <div className="flex items-center space-x-3">
                      <span className="font-bold text-sm text-slate-700">{file.file.name}</span>
                      <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${
                        file.status === 'editing' || file.status === 'completed' ? 'bg-green-100 text-green-700' :
                        file.status === 'error' ? 'bg-red-100 text-red-700' :
                        'bg-blue-100 text-blue-700'
                      }`}>
                        {file.status}
                      </span>
                   </div>
                   {file.status === 'editing' && (
                     <div className="text-[10px] text-gray-400 font-medium">Ready for review</div>
                   )}
                </div>

                {file.status === 'editing' && file.result && (
                  <LogicModelEditor 
                    model={file.result} 
                    onUpdate={(updated) => updateModel(file.id, updated)}
                    onReAnalyze={() => reAnalyzeModel(file.id)}
                    isAnalyzing={false}
                  />
                )}

                {(file.status === 'analyzing' || file.status === 'converting') && (
                  <div className="bg-white border rounded-xl p-20 flex flex-col items-center justify-center space-y-4 shadow-sm">
                      <div className="animate-spin rounded-full h-12 w-12 border-4 border-indigo-500 border-t-transparent"></div>
                      <p className="font-bold text-slate-600">
                        {file.status === 'converting' ? 'Reading Document...' : 'AI Vision Analysis...'}
                      </p>
                      <p className="text-xs text-slate-400">
                         {file.file.name.endsWith('.pdf') ? 'Scanning visual layout for groups & categories' : 'Parsing text structure'}
                      </p>
                  </div>
                )}

                {file.status === 'error' && (
                  <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
                    <p className="text-red-700 font-bold mb-2">Processing Error</p>
                    <p className="text-red-600 text-sm">{file.error}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

const checkLibs = () => {
  if (!window.mammoth) console.warn('Mammoth.js not loaded');
  if (!window.pdfjsLib) console.warn('PDF.js not loaded');
  if (!window.JSZip) console.warn('JSZip not loaded');
  if (!window.TurndownService) console.warn('TurndownService not loaded');
  if (!(window as any).docx) console.warn('docx-preview not loaded');
  if (!(window as any).html2canvas) console.warn('html2canvas not loaded');
};

export const convertPdfToImages = async (file: File): Promise<string[]> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    const images: string[] = [];

    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const viewport = page.getViewport({ scale: 2.0 }); // High scale for better text recognition
      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');

      canvas.height = viewport.height;
      canvas.width = viewport.width;

      if (context) {
        await page.render({ canvasContext: context, viewport: viewport }).promise;
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        images.push(dataUrl.split(',')[1]);
      }
    }
    return images;
  } catch (error) {
    console.error('PDF Image Conversion Error:', error);
    throw new Error('Failed to convert PDF to images for analysis.');
  }
};

export const convertDocxToImages = async (file: File): Promise<string[]> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const container = document.createElement('div');
    container.style.position = 'absolute';
    container.style.left = '-9999px';
    container.style.top = '0';
    container.style.width = '1000px'; // Fixed width to force layout
    container.style.backgroundColor = 'white';
    document.body.appendChild(container);

    // Render DOCX to DOM
    await (window as any).docx.renderAsync(arrayBuffer, container, container, {
        inWrapper: false,
        ignoreWidth: false,
        ignoreHeight: false,
        breakPages: true
    });

    // Capture the rendered content
    // Note: docx-preview might create multiple pages or one long page. 
    // We will capture the whole container.
    const canvas = await (window as any).html2canvas(container, {
        scale: 1.5,
        useCORS: true
    });

    document.body.removeChild(container);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
    return [dataUrl.split(',')[1]];

  } catch (error) {
    console.error('DOCX Image Conversion Error:', error);
    throw new Error('Failed to convert Word document to images.');
  }
};

export const convertPptxToImages = async (file: File): Promise<string[]> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new window.JSZip();
    await zip.loadAsync(arrayBuffer);

    // Filter for slide XML files
    const slideFiles = Object.keys(zip.files).filter(name => 
      name.startsWith('ppt/slides/slide') && name.endsWith('.xml')
    );

    slideFiles.sort((a, b) => {
      const getNum = (str: string) => {
        const match = str.match(/slide(\d+)\.xml/);
        return match ? parseInt(match[1], 10) : 0;
      };
      return getNum(a) - getNum(b);
    });

    const images: string[] = [];
    const parser = new DOMParser();

    // Loop through slides and reconstruct simplified visual layout as SVG
    for (const slidePath of slideFiles) {
      const fileEntry = zip.file(slidePath);
      if (!fileEntry) continue;

      const content = await fileEntry.async('text');
      const xmlDoc = parser.parseFromString(content, 'application/xml');

      // Default PPTX slide size (16:9 1080p approx) in EMUs. 
      // 1 inch = 914400 EMUs. 
      // Let's assume standard 1280x720 pixels for the SVG canvas.
      const slideWidth = 1280;
      const slideHeight = 720;

      // EMU to Pixel conversion factor (approximate)
      // Standard: 96 DPI -> 914400 / 96 = 9525 EMUs per pixel
      const emuToPx = (emu: number) => emu / 9525;

      // Extract shapes
      const spTags = xmlDoc.getElementsByTagName('p:sp');
      let svgContent = '';

      Array.from(spTags).forEach((sp) => {
          // Get Transformation (Geometry)
          const xfrm = sp.getElementsByTagName('a:xfrm')[0];
          if (!xfrm) return;

          const off = xfrm.getElementsByTagName('a:off')[0];
          const ext = xfrm.getElementsByTagName('a:ext')[0];

          if (off && ext) {
              const x = emuToPx(parseInt(off.getAttribute('x') || '0'));
              const y = emuToPx(parseInt(off.getAttribute('y') || '0'));
              const w = emuToPx(parseInt(ext.getAttribute('cx') || '0'));
              const h = emuToPx(parseInt(ext.getAttribute('cy') || '0'));

              // Get Text content
              const txBody = sp.getElementsByTagName('p:txBody')[0];
              if (txBody) {
                  const textNodes = txBody.getElementsByTagName('a:t');
                  const text = Array.from(textNodes).map(n => n.textContent).join(' ');
                  if (text.trim()) {
                      // Draw a rectangle and text in SVG
                      // We use a simple rect to show boundaries for the AI to understand grouping
                      svgContent += `
                          <rect x="${x}" y="${y}" width="${w}" height="${h}" fill="rgba(200, 200, 255, 0.3)" stroke="blue" stroke-width="1" />
                          <text x="${x + 10}" y="${y + 20}" font-family="Arial" font-size="12" fill="black">
                            ${text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').substring(0, 100)}...
                          </text>
                          <foreignObject x="${x}" y="${y}" width="${w}" height="${h}">
                            <div xmlns="http://www.w3.org/1999/xhtml" style="font-family:Arial;font-size:12px;color:black;padding:5px;overflow:hidden;height:100%;">
                                ${text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}
                            </div>
                          </foreignObject>
                      `;
                  }
              }
          }
      });

      // Wrap in SVG
      const svg = `
        <svg xmlns="http://www.w3.org/2000/svg" width="${slideWidth}" height="${slideHeight}" style="background-color: white;">
            ${svgContent}
        </svg>
      `;

      // Convert SVG to Canvas to Base64
      const canvas = document.createElement('canvas');
      canvas.width = slideWidth;
      canvas.height = slideHeight;
      const ctx = canvas.getContext('2d');

      if (ctx) {
          const img = new Image();
          const svgBlob = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });
          const url = URL.createObjectURL(svgBlob);

          await new Promise<void>((resolve, reject) => {
              img.onload = () => {
                  ctx.fillStyle = 'white';
                  ctx.fillRect(0, 0, slideWidth, slideHeight);
                  ctx.drawImage(img, 0, 0);
                  URL.revokeObjectURL(url);
                  resolve();
              };
              img.onerror = reject;
              img.src = url;
          });

          const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
          images.push(dataUrl.split(',')[1]);
      }
    }

    return images;

  } catch (error) {
    console.error('PPTX Image Conversion Error:', error);
    throw new Error('Failed to convert PowerPoint slides to images.');
  }
};

// Legacy/Fallback Text Extractions
export const extractTextFromPdf = async (file: File): Promise<string> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = '';
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(' ');
      fullText += `\n\n## Page ${i}\n\n${pageText}`;
    }
    return fullText;
  } catch (error) {
    console.error('PDF Extraction Error:', error);
    throw new Error('Failed to extract text from PDF.');
  }
};

export const extractTextFromDocx = async (file: File): Promise<string> => {
  checkLibs();
  try {
    const arrayBuffer = await file.arrayBuffer();
    const result = await window.mammoth.convertToHtml({ arrayBuffer });
    const turndownService = new window.TurndownService({ headingStyle: 'atx', bulletListMarker: '-' });
    return turndownService.turndown(result.value);
  } catch (error) {
    console.error('Docx Extraction Error:', error);
    throw new Error('Failed to extract text from DOCX.');
  }
};

export const extractTextFromPptx = async (file: File): Promise<string> => {
    // Kept as fallback if needed, or used if Vision fails
    // (Implementation matches previous version)
    checkLibs();
    try {
        const arrayBuffer = await file.arrayBuffer();
        const zip = new window.JSZip();
        await zip.loadAsync(arrayBuffer);
        const slideFiles = Object.keys(zip.files).filter(name => 
            name.startsWith('ppt/slides/slide') && name.endsWith('.xml')
        );
        slideFiles.sort((a, b) => {
            const getNum = (str: string) => { const match = str.match(/slide(\d+)\.xml/); return match ? parseInt(match[1], 10) : 0; };
            return getNum(a) - getNum(b);
        });
        let fullText = '';
        const parser = new DOMParser();
        for (const slidePath of slideFiles) {
            const entry = zip.file(slidePath);
            if(entry) {
                const content = await entry.async('text');
                const xmlDoc = parser.parseFromString(content, 'application/xml');
                const textNodes = xmlDoc.getElementsByTagName('a:t');
                const slideText = Array.from(textNodes).map(node => node.textContent).join(' ');
                if (slideText.trim()) fullText += `\n\n## Slide\n\n${slideText}`;
            }
        }
        return fullText;
    } catch (e) { throw new Error('PPTX Text Extraction failed'); }
};

export const convertFileToMarkdown = async (file: File): Promise<string> => {
  const name = file.name.toLowerCase();
  if (name.endsWith('.pdf')) return extractTextFromPdf(file);
  if (name.endsWith('.docx')) return extractTextFromDocx(file);
  if (name.endsWith('.pptx')) return extractTextFromPptx(file);
  throw new Error(`Unsupported file format: ${file.name}`);
};

