import { parseAndCritiqueLogicModel } from './services/geminiService';

const App: React.FC = () => {
  const [files, setFiles] = useState<ProcessingFile[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const processingRef = useRef(false);

  const handleFilesSelected = (newFiles: File[]) => {
    const newProcessingFiles: ProcessingFile[] = newFiles.map(file => ({
      id: Math.random().toString(36).substring(7),
      file,
      status: 'pending'
    }));
    setFiles(prev => [...prev, ...newProcessingFiles]);
  };

  useEffect(() => {
    const processQueue = async () => {
      if (processingRef.current) return;
      const pendingFile = files.find(f => f.status === 'pending');
      if (!pendingFile) return;

      processingRef.current = true;
      setIsProcessing(true);
      const fileId = pendingFile.id;

      try {
        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'converting' } : f));

        let inputForGemini: string | string[];
        const fileName = pendingFile.file.name.toLowerCase();

        // 1. Attempt Vision Processing for ALL types to detect structure
        try {
            if (fileName.endsWith('.pdf')) {
                inputForGemini = await convertPdfToImages(pendingFile.file);
            } else if (fileName.endsWith('.docx')) {
                inputForGemini = await convertDocxToImages(pendingFile.file);
            } else if (fileName.endsWith('.pptx')) {
                inputForGemini = await convertPptxToImages(pendingFile.file);
            } else {
                throw new Error("Unsupported format for vision");
            }
        } catch (visionError) {
            console.warn("Vision processing failed, falling back to text extraction:", visionError);
            // Fallback to text extraction if visual rendering fails
            inputForGemini = await convertFileToMarkdown(pendingFile.file);
        }

        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'analyzing' } : f));
        const result = await parseAndCritiqueLogicModel(inputForGemini);

        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'editing', result } : f));
      } catch (error: any) {
        setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'error', error: error.message } : f));
      } finally {
        processingRef.current = false;
        setIsProcessing(false);
      }
    };
    processQueue();
  }, [files, isProcessing]);

  const updateModel = (fileId: string, updatedModel: LogicModel) => {
    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, result: updatedModel } : f));
  };

  const reAnalyzeModel = async (fileId: string) => {
    const file = files.find(f => f.id === fileId);
    if (!file || !file.result) return;

    setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'analyzing' } : f));
    setIsProcessing(true);

    try {
      // For re-analysis, we just use the text representation of the current state
      const formatGroups = (groups: LogicModelGroup[]) => 
         groups.map(g => `Group: ${g.name}\nItems: ${g.items.join(', ')}`).join('\n');

      const textForCritique = `
        Organization: ${file.result.organization}
        Program: ${file.result.program}
        Problem: ${file.result.problemStatement.content}
        Inputs: \n${formatGroups(file.result.inputs.content)}
        Activities: \n${formatGroups(file.result.activities.content)}
        Outputs: \n${formatGroups(file.result.outputs.content)}
        Short-Term: \n${formatGroups(file.result.shortTermOutcomes.content)}
        Medium-Term: \n${formatGroups(file.result.mediumTermOutcomes.content)}
        Long-Term: \n${formatGroups(file.result.longTermOutcomes.content)}
        Impact: \n${formatGroups(file.result.impact.content)}
      `;
      const result = await parseAndCritiqueLogicModel(textForCritique);
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'editing', result } : f));
    } catch (e: any) {
      setFiles(prev => prev.map(f => f.id === fileId ? { ...f, status: 'error', error: e.message } : f));
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExportCSV = () => {
    const completed = files.filter(f => (f.status === 'editing' || f.status === 'completed') && f.result);
    if (completed.length === 0) return;

    const headers = ['Organization', 'Program', 'Domain', 'Group', 'Content'];
    const rows: string[][] = [];

    completed.forEach(f => {
      const m = f.result!;

      const pushGroups = (domain: string, groups: LogicModelGroup[]) => {
         groups.forEach(g => {
            g.items.forEach(item => {
               rows.push([m.organization, m.program, domain, g.name, item]);
            });
         });
      };

      rows.push([m.organization, m.program, 'Problem Statement', 'General', m.problemStatement.content]);
      pushGroups('Inputs', m.inputs.content);
      pushGroups('Activities', m.activities.content);
      pushGroups('Outputs', m.outputs.content);
      pushGroups('Short-Term Outcomes', m.shortTermOutcomes.content);
      pushGroups('Medium-Term Outcomes', m.mediumTermOutcomes.content);
      pushGroups('Long-Term Outcomes', m.longTermOutcomes.content);
      pushGroups('Impact', m.impact.content);
    });

    const csvContent = [
      headers.map(h => `"${h}"`).join(','),
      ...rows.map(row => row.map(c => `"${String(c).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `logic_models_granular_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="bg-indigo-600 text-white p-1.5 rounded-lg shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" />
                </svg>
             </div>
             <h1 className="text-xl font-bold text-slate-800">Logic Model Refiner <span className="text-xs font-normal text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full ml-2">Vision Enabled</span></h1>
          </div>
          <button 
            onClick={handleExportCSV}
            className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-700 transition-colors shadow-sm disabled:opacity-50"
            disabled={files.length === 0}
          >
            Export All Data
          </button>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        <section className="text-center space-y-3 max-w-3xl mx-auto">
            <h2 className="text-3xl font-bold text-slate-900 leading-tight">Extract & Refine Your Program Data</h2>
            <p className="text-slate-600">
                Upload logic models (PDF, Word, or PowerPoint). 
                <strong> AI Vision</strong> is used to detect visual layout, columns, and stakeholder groupings.
            </p>
        </section>

        <section>
          <FileUpload onFilesSelected={handleFilesSelected} disabled={isProcessing} />
        </section>

        {files.length > 0 && (
          <div className="space-y-12">
            {files.map(file => (
              <div key={file.id} className="space-y-4">
                <div className="flex items-center justify-between bg-white p-3 rounded-lg border border-gray-200 shadow-sm">
                   <div className="flex items-center space-x-3">
                      <span className="font-bold text-sm text-slate-700">{file.file.name}</span>
                      <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${
                        file.status === 'editing' || file.status === 'completed' ? 'bg-green-100 text-green-700' :
                        file.status === 'error' ? 'bg-red-100 text-red-700' :
                        'bg-blue-100 text-blue-700'
                      }`}>
                        {file.status}
                      </span>
                   </div>
                   {file.status === 'editing' && (
                     <div className="text-[10px] text-gray-400 font-medium">Ready for review</div>
                   )}
                </div>

                {file.status === 'editing' && file.result && (
                  <LogicModelEditor 
                    model={file.result} 
                    onUpdate={(updated) => updateModel(file.id, updated)}
                    onReAnalyze={() => reAnalyzeModel(file.id)}
                    isAnalyzing={false}
                  />
                )}

                {(file.status === 'analyzing' || file.status === 'converting') && (
                  <div className="bg-white border rounded-xl p-20 flex flex-col items-center justify-center space-y-4 shadow-sm">
                      <div className="animate-spin rounded-full h-12 w-12 border-4 border-indigo-500 border-t-transparent"></div>
                      <p className="font-bold text-slate-600">
                        {file.status === 'converting' ? 'Reading Visual Layout...' : 'AI Vision Analysis...'}
                      </p>
                      <p className="text-xs text-slate-400">
                         Scanning for columns, groups, and categories...
                      </p>
                  </div>
                )}

                {file.status === 'error' && (
                  <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
                    <p className="text-red-700 font-bold mb-2">Processing Error</p>
                    <p className="text-red-600 text-sm">{file.error}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { LogicModel, LogicModelGroup } from '../types';

interface LogicModelEditorProps {
  model: LogicModel;
  onUpdate: (updatedModel: LogicModel) => void;
  onReAnalyze: () => void;
  isAnalyzing: boolean;
}

const EditableGroupSection: React.FC<{
  title: string;
  field: keyof LogicModel;
  model: LogicModel;
  onUpdate: (updatedModel: LogicModel) => void;
}> = ({ title, field, model, onUpdate }) => {
  const fieldData = model[field] as { content: LogicModelGroup[], critique: string };
  const groups = fieldData.content;

  const handleGroupChange = (groupIndex: number, newItemsText: string) => {
    const newGroups = [...groups];
    newGroups[groupIndex].items = newItemsText.split('\n').filter(l => l.trim() !== '');

    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  const handleGroupNameChange = (groupIndex: number, newName: string) => {
    const newGroups = [...groups];
    newGroups[groupIndex].name = newName;
    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  const addGroup = () => {
    const newGroups = [...groups, { name: 'New Category', items: [] }];
    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  const removeGroup = (index: number) => {
    if (!window.confirm("Remove this group?")) return;
    const newGroups = groups.filter((_, i) => i !== index);
    onUpdate({
      ...model,
      [field]: { ...fieldData, content: newGroups }
    });
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 border-b border-gray-100 pb-8 mb-8 last:border-0">
      {/* Title Column */}
      <div className="lg:col-span-3">
         <h4 className="text-sm font-bold uppercase tracking-wider text-slate-500 mb-1">{title}</h4>
      </div>

      {/* Content Column (Groups) */}
      <div className="lg:col-span-2 space-y-6">
        {groups.map((group, idx) => (
          <div key={idx} className="relative bg-gray-50/50 rounded-lg p-3 border border-gray-200 group-hover:border-blue-300 transition-colors">
            <div className="flex items-center justify-between mb-2">
              <input
                className="bg-transparent text-sm font-bold text-slate-700 focus:outline-none focus:border-b focus:border-blue-500 px-1"
                value={group.name}
                onChange={(e) => handleGroupNameChange(idx, e.target.value)}
                placeholder="Group Name (e.g., Staff)"
              />
              <button 
                onClick={() => removeGroup(idx)}
                className="text-gray-400 hover:text-red-500 text-xs px-2"
                title="Remove Group"
              >
                ✕
              </button>
            </div>
            <textarea
              className="w-full min-h-[80px] p-3 text-sm border border-gray-200 bg-white rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all font-mono leading-relaxed"
              value={group.items.join('\n')}
              onChange={(e) => handleGroupChange(idx, e.target.value)}
              placeholder="List items here..."
            />
          </div>
        ))}
        <button 
          onClick={addGroup}
          className="w-full py-2 border-2 border-dashed border-gray-200 rounded-lg text-xs font-bold text-gray-400 hover:text-blue-600 hover:border-blue-300 hover:bg-blue-50 transition-all flex items-center justify-center space-x-1"
        >
          <span>+ Add Sub-Group</span>
        </button>
      </div>

      {/* Critique Column */}
      <div className="lg:col-span-1">
        <div className="bg-amber-50 border border-amber-100 rounded-lg p-4 sticky top-24">
          <h5 className="text-[10px] font-bold text-amber-700 uppercase tracking-widest mb-2 flex items-center">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 mr-1">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
            </svg>
            AI Critique
          </h5>
          <p className="text-xs text-amber-900 leading-relaxed italic">
            {fieldData.critique || "Everything looks good here! No specific suggestions."}
          </p>
        </div>
      </div>
    </div>
  );
};

