// Ensure libraries are available globally from index.html
declare const html2canvas: any;
declare const jspdf: any;
declare const JSZip: any;

export const generatePdfFromElement = async (elementId: string, filename: string): Promise<Blob | null> => {
  const container = document.getElementById(elementId);
  if (!container) {
    console.error(`Element with id ${elementId} not found`);
    return null;
  }

  try {
    const { jsPDF } = jspdf;
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    });

    const pdfWidth = 297;
    const pdfHeight = 210;

    // Check if we have multiple pages rendered
    const pages = container.querySelectorAll('.pdf-page');
    const elementsToCapture = pages.length > 0 ? Array.from(pages) : [container];

    for (let i = 0; i < elementsToCapture.length; i++) {
        const element = elementsToCapture[i] as HTMLElement;

        // Add new page if not the first
        if (i > 0) {
            doc.addPage();
        }

        const canvas = await html2canvas(element, {
          scale: 2, // Higher scale for better quality
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.95);

        // Calculate dimensions to fit exactly on A4 Landscape
        // We enforce the aspect ratio of the captured element to fit the page height/width
        const imgProps = doc.getImageProperties(imgData);
        const ratio = imgProps.width / imgProps.height;
        const width = pdfWidth;
        const height = width / ratio;

        // Center vertically if height is less than page height (rare with our fixed layout)
        const y = height < pdfHeight ? (pdfHeight - height) / 2 : 0;

        doc.addImage(imgData, 'JPEG', 0, y, width, height);
    }

    return doc.output('blob');
  } catch (error) {
    console.error('PDF Generation Error:', error);
    throw error;
  }
};

export const createZipFromBlobs = async (files: { name: string; blob: Blob }[]): Promise<void> => {
    const zip = new JSZip();

    files.forEach(file => {
        zip.file(file.name, file.blob);
    });

    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `logic_models_batch_${new Date().toISOString().slice(0, 10)}.zip`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { getAiCritiquePrompt } from "../constants";
import { LogicModel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const groupSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING, description: "Name of the category or group (e.g., 'Staff', 'Parents'). Use 'General' if no group." },
    items: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["name", "items"]
};

const fieldSchema = (contentType: Type): Schema => ({
  type: Type.OBJECT,
  properties: {
    // If it's an ARRAY type field, the content is an array of Groups
    content: contentType === Type.ARRAY 
      ? { type: Type.ARRAY, items: groupSchema } 
      : { type: Type.STRING },
    critique: { type: Type.STRING, description: "Constructive feedback on this specific section" }
  },
  required: ["content", "critique"]
});

const logicModelSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    organization: { type: Type.STRING, description: "Name of the organization. Infer from content (e.g. 'Zoo Content' -> 'Philadelphia Zoo') if not explicitly stated." },
    program: { type: Type.STRING },
    // Changed problemStatement to use ARRAY type to support groupings
    problemStatement: fieldSchema(Type.ARRAY),
    inputs: fieldSchema(Type.ARRAY),
    activities: fieldSchema(Type.ARRAY),
    outputs: fieldSchema(Type.ARRAY),
    shortTermOutcomes: fieldSchema(Type.ARRAY),
    mediumTermOutcomes: fieldSchema(Type.ARRAY),
    longTermOutcomes: fieldSchema(Type.ARRAY),
    impact: fieldSchema(Type.ARRAY),
  },
  required: [
    "organization", "program", "problemStatement", "inputs", "activities", 
    "outputs", "shortTermOutcomes", "mediumTermOutcomes", "longTermOutcomes", "impact"
  ],
};

// Input can be a string (markdown) or an array of strings (base64 images)
export const parseAndCritiqueLogicModel = async (input: string | string[]): Promise<LogicModel> => {
  const isVision = Array.isArray(input);
  const prompt = getAiCritiquePrompt(isVision);

  let contents: any;

  if (isVision) {
    // Construct the payload for vision (text prompt + images)
    const parts: any[] = [{ text: prompt }];
    (input as string[]).forEach(base64Image => {
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: base64Image
        }
      });
    });
    contents = { parts };
  } else {
    // Text-only payload
    contents = [
      { text: prompt },
      { text: `\n\nDocument Content:\n---\n${input}\n---` }
    ];
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: contents,
    config: {
      responseMimeType: 'application/json',
      responseSchema: logicModelSchema,
      temperature: 0.2,
    }
  });

  if (!response.text) throw new Error("No response from AI.");
  return JSON.parse(response.text) as LogicModel;
};

