            ))}
          </ul>
        </div>
      ))}
    </div>
  </div>
);

const ContextGroup: React.FC<{ title: string; groups: LogicModelGroup[] }> = ({ title, groups }) => {
    // Only render if there is actual content
    const hasContent = groups.some(g => g.items.length > 0);
    if (!hasContent) return null;

